mapper.select:
SELECT u.id, u.username, u.email, u.phone, u.avatar, u.nickname, u.status, u.create_time, u.update_time, d.id as dept_id, d.dept_name, d.dept_code, r.id as role_id, r.role_name, r.role_code FROM sys_user u LEFT JOIN sys_user_dept ud ON u.id = ud.user_id LEFT JOIN sys_dept d ON ud.dept_id = d.id LEFT JOIN sys_user_role ur ON u.id = ur.user_id LEFT JOIN sys_role r ON ur.role_id = r.id
AND u.username LIKE CONCAT('%', #{username}, '%')
AND u.status = #{status}
AND d.id = #{deptId}
ORDER BY u.create_time DESC
